edits.after:
if ((!pte_write(pte) && gup_must_unshare(vma, flags, page)) ||
    (pte_write(pte) && page && PageAnon(page) && !PageAnonExclusive(page))) {
	if (pte_write(pte)) {
		ptep_set_wrprotect(mm, address, ptep);
		flush_tlb_page(vma, address);
		/*
		 * We renamed the page as R/O, effectively unsharing it.
		 * Return NULL so the fault handler can handle the CoW.
		 */
		page = NULL;
	} else {
		page = ERR_PTR(-EMLINK);
	}
	goto out;
}

